-- State transitions declared for Journal: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION accounting.journals_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('approved', 'posted'), ('draft', 'pending_approval'), ('draft', 'rejected'), ('pending_approval', 'approved'), ('pending_approval', 'rejected'), ('posted', 'voided'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: journals.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_journals__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS journals_status_transition_check ON accounting.journals;
CREATE TRIGGER journals_status_transition_check
    BEFORE UPDATE OF "status" ON accounting.journals
    FOR EACH ROW EXECUTE FUNCTION accounting.journals_status_transition_check();
